% make_results_VR_binaryclassification.m
%
% Computes variance reduction factors for the GP binary classification experiments
% and writes the LaTeX tables for:
%
%   Table 7  (Section 5.2)    -- Heart (d=270) and Australian (d=690)
%   Table 12 (Appendix A.1)   -- German (d=1000), Pima (d=532), Ripley (d=250)
%
% Reads:
%   ../results/LogisticRegression_GP/<Dataset>_repeat<r>_Marg_fixedhypers_VR_<T>.mat
%   Each file contains: means (1 x d), means_cv (1 x d)
%   Generated by demBinaryClassification_Marg_fixedhypers_gimala_VR(rep, T).
%
% To reproduce all four n columns, run run_VR_experiments.m first (100 reps,
% T in {1000, 10000, 50000, 200000}).  If only some T values are available,
% this script writes '--' for any missing (dataset, T) combination.
%
% Output (written to ../diagrams/):
%   VR_GP_classification_table7.txt    LaTeX rows for Table 7
%   VR_GP_classification_table12.txt   LaTeX rows for Table 12

outdir = '../diagrams/';
resdir = '../results/LogisticRegression_GP/';

Repeats = 100;
T_list  = [1000, 10000, 50000, 200000];

datasets = {'Heart', 'Australian', 'German', 'Pima', 'Ripley'};
d_vals   = [270,    690,          1000,     532,    250   ];

ratio_min = NaN(length(datasets), length(T_list));
ratio_max = NaN(length(datasets), length(T_list));

for di = 1:length(datasets)
    dataName = datasets{di};
    for ti = 1:length(T_list)
        T = T_list(ti);
        means_all    = [];
        means_cv_all = [];

        for r = 1:Repeats
            fname = [resdir dataName '_repeat' num2str(r) ...
                     '_Marg_fixedhypers_VR_' num2str(T) '.mat'];
            if exist(fname, 'file')
                tmp = load(fname, 'means', 'means_cv');
                means_all    = [means_all;    tmp.means];
                means_cv_all = [means_cv_all; tmp.means_cv];
            end
        end

        if size(means_all, 1) >= 2
            var_plain = var(means_all,    [], 1);
            var_vr    = var(means_cv_all, [], 1);
            ratio = var_plain ./ max(var_vr, 1e-12);
            ratio_min(di, ti) = min(ratio);
            ratio_max(di, ti) = max(ratio);
        end
    end
end

% Helper: write one table (subset of dataset rows) to a file.
function write_table(fname, row_idx, datasets, d_vals, T_list, ratio_min, ratio_max)
    fid = fopen(fname, 'w');
    fprintf(fid, 'Dataset');
    for ti = 1:length(T_list)
        fprintf(fid, ' & $n = %s$', num2str(T_list(ti)));
    end
    fprintf(fid, ' \\\\\n\\midrule\n');
    for di = row_idx
        fprintf(fid, '%s ($d=%d$)', datasets{di}, d_vals(di));
        for ti = 1:length(T_list)
            if ~isnan(ratio_min(di, ti))
                fprintf(fid, ' & %.2f-%.2f', ratio_min(di, ti), ratio_max(di, ti));
            else
                fprintf(fid, ' & --');
            end
        end
        fprintf(fid, ' \\\\\n');
    end
    fclose(fid);
end

% Table 7: Heart and Australian
write_table([outdir 'VR_GP_classification_table7.txt'], [1 2], ...
            datasets, d_vals, T_list, ratio_min, ratio_max);
fprintf('Written: VR_GP_classification_table7.txt  (Table 7, Section 5.2)\n');

% Table 12: German, Pima, Ripley
write_table([outdir 'VR_GP_classification_table12.txt'], [3 4 5], ...
            datasets, d_vals, T_list, ratio_min, ratio_max);
fprintf('Written: VR_GP_classification_table12.txt  (Table 12, Appendix A.1)\n');
